"use strict";
// Cyrus mod networking (service 0.6): the capability manifest a plugin must ship to use the
// network through the Nxeon wrapper (dev.nxeon.cyrus.net.NxHttp). Pure and offline.
//
// src/main/resources/nx-capabilities.yml (written by the model, checked here, never trusted):
//   version: 1
//   network:
//     hosts:
//       - host: api.example.com          # exact hostname: no IPs, no wildcards, no ports (443 only)
//         purpose: Show the weather in the scoreboard
//     playerData: [names]                # any of names | chat | ip ; [] or "none" = no player data
//     maxResponseKiB: 256                # 16..1024
//   secrets:                             # values are typed in by the server owner (nx-secrets.yml)
//     - name: weather_key
//       host: api.example.com            # the wrapper only ever sends it to this host
//       header: X-Api-Key                # or `url: true` when the secret is a whole URL (webhooks)
//       description: Your API key from example.com
//   ai: false                            # true = may call the Nxeon AI gateway (no declared host needed)
//
// The same rules live in lib/cyrus/capabilities.ts (portal); both read rules/net-policy.json
// and test/modbuilder-capabilities.test.ts checks they agree.

const crypto = require("crypto");
const path = require("path");
const fs = require("fs");

const POLICY = JSON.parse(fs.readFileSync(path.join(__dirname, "rules", "net-policy.json"), "utf8"));
const MANIFEST_FILE = "nx-capabilities.yml";
const STAMP_FILE = "nx-capabilities.properties";

const DENIED = [];
for (const [reason, list] of Object.entries(POLICY.deniedSuffixes)) for (const s of list) DENIED.push([s, reason]);

const LABEL = /^(?!-)[a-z0-9-]{1,63}(?<!-)$/;
const IPV4ISH = /^[0-9.]+$/;

/** Why a hostname may not be declared, or null when it may. */
function hostProblem(h) {
  if (typeof h !== "string" || !h) return "is empty";
  if (h !== h.trim() || /\s/.test(h)) return "contains spaces";
  if (/[A-Z]/.test(h)) return "must be lower case";
  if (h.includes("*")) return "must be one exact name (no wildcards)";
  if (h.includes(":") || h.includes("[")) return "must be a name without a port or IP address";
  if (h.includes("/") || h.includes("@")) return "must be a bare hostname (no scheme, path or user)";
  if (h.endsWith(".")) return "must not end with a dot";
  if (h.length > 253) return "is too long";
  if (IPV4ISH.test(h) || /^0x/i.test(h)) return "is an IP address (declare a hostname)";
  const labels = h.split(".");
  if (labels.length < 2) return "needs a domain (for example api.example.com)";
  if (!labels.every((l) => LABEL.test(l))) return "is not a valid hostname";
  if (!/^[a-z]{2,63}$|^xn--[a-z0-9-]{1,59}$/.test(labels[labels.length - 1])) return "has no valid top-level domain";
  for (const [suffix, reason] of DENIED) if (h === suffix || h.endsWith("." + suffix)) return `is not allowed (${reason})`;
  return null;
}

function cleanText(x, max) {
  return String(x == null ? "" : x).replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
}

