def parse_class(b):
    """Minimal but complete class-file parser. Returns dict."""
    p = 0
    magic, minor, major, n = struct.unpack('>IHHH', b[:10]); p = 10
    cp = [None] * n
    i = 1
    while i < n:
        t = b[p]; p += 1
        if t == 1:
            l = struct.unpack('>H', b[p:p+2])[0]; p += 2
            cp[i] = (1, b[p:p+l].decode('utf-8', 'replace')); p += l
        elif t in (3, 4): cp[i] = (t, b[p:p+4]); p += 4
        elif t in (5, 6): cp[i] = (t,); p += 8; i += 1
        elif t in (7, 8, 16, 19, 20): cp[i] = (t, struct.unpack('>H', b[p:p+2])[0]); p += 2
        elif t in (9, 10, 11, 12, 17, 18): cp[i] = (t, *struct.unpack('>HH', b[p:p+4])); p += 4
        elif t == 15: cp[i] = (t, b[p], struct.unpack('>H', b[p+1:p+3])[0]); p += 3
        else: raise ValueError('cp tag %d' % t)
        i += 1
    def utf(ix): return cp[ix][1] if cp[ix] and cp[ix][0] == 1 else ''
    def cls(ix): return utf(cp[ix][1]) if cp[ix] and cp[ix][0] == 7 else ''
    acc, this, sup, ni = struct.unpack('>HHHH', b[p:p+8]); p += 8
    ifaces = []
    for _ in range(ni):
        ifaces.append(cls(struct.unpack('>H', b[p:p+2])[0])); p += 2
    def skip_attrs(p):
        na = struct.unpack('>H', b[p:p+2])[0]; p += 2
        for _ in range(na):
            ln = struct.unpack('>I', b[p+2:p+6])[0]; p += 6 + ln
        return p
    def parse_ev(p):
        tag = chr(b[p]); p += 1
        if tag in 'BCDFIJSZs': return p + 2, ('c', utf(struct.unpack('>H', b[p:p+2])[0]) if tag == 's' else None)
        if tag == 'e':
            tn, cn = struct.unpack('>HH', b[p:p+4]); return p + 4, ('e', utf(cn))
        if tag == 'c': return p + 2, None
        if tag == '@': return parse_ann(p)[0], None
