def analyse_datapack(path):
    z = read_zip(path); r = {'ok': False}
    if not z: r['error'] = 'not a zip'; return r
    r['ok'] = True; names = [n for n in z.namelist() if not n.endswith('/')]
    r['files'] = len(names); r['uncompressed'] = sum(z.getinfo(n).file_size for n in names)
    mc = next((n for n in names if n.endswith('pack.mcmeta') and n.count('/') <= 1), None)
    if mc:
        try:
            raw = z.read(mc).decode('utf-8-sig', 'replace'); j = json.loads(raw); p = j.get('pack', {})
            r['pack_format'] = p.get('pack_format'); r['supported_formats'] = p.get('supported_formats'); r['min_format'] = p.get('min_format'); r['max_format'] = p.get('max_format')
            r['overlays'] = len((j.get('overlays') or {}).get('entries', []))
        except Exception: r['mcmeta_error'] = True
    reg = collections.Counter(); ns = set(); cmds = collections.Counter(); funcs = 0; fn_lines = 0
    for n in names:
        m = re.search(r'(?:^|/)data/([^/]+)/(.+)$', n)
        if not m: continue
        ns.add(m.group(1)); rest = m.group(2).split('/')
        if rest[0] == 'worldgen' and len(rest) > 2: key = 'worldgen/' + rest[1]
        elif rest[0] == 'tags' and len(rest) > 2: key = 'tags/' + rest[1]
        elif rest[0] in ('function', 'functions'): key = 'function'
        else: key = rest[0]
        reg[key] += 1
        if key == 'function' and n.endswith('.mcfunction'):
            funcs += 1
            try:
                for ln in z.read(n).decode('utf-8', 'replace').splitlines():
                    ln = ln.strip()
                    if not ln or ln.startswith('#'): continue
                    t = ln.lstrip('$').split()[0] if ln.lstrip('$').split() else ''
                    if re.match(r'^[a-z_]+$', t): cmds[t] += 1; fn_lines += 1
            except Exception: pass
    r['namespaces'] = sorted(ns)[:10]; r['registries'] = dict(reg); r['function_files'] = funcs; r['function_lines'] = fn_lines; r['mcfunction_commands'] = dict(cmds.most_common(15))
    r['has_dimension_or_worldgen'] = any(k.startswith('worldgen') or k in ('dimension', 'dimension_type') for k in reg)
    r['has_enchantment'] = 'enchantment' in reg
    r['has_predicate_or_modifier'] = any(k in reg for k in ('predicate', 'item_modifier'))
    return r

def analyse_resourcepack(path):
    z = read_zip(path); r = {'ok': False}
    if not z: r['error'] = 'not a zip'; return r
    r['ok'] = True; infos = [i for i in z.infolist() if not i.filename.endswith('/')]
    r['files'] = len(infos); r['uncompressed'] = sum(i.file_size for i in infos)
    mc = next((i.filename for i in infos if i.filename.endswith('pack.mcmeta') and i.filename.count('/') <= 1), None)
    if mc:
        try:
            j = json.loads(z.read(mc).decode('utf-8-sig', 'replace')); p = j.get('pack', {})
            r['pack_format'] = p.get('pack_format'); r['supported_formats'] = p.get('supported_formats'); r['min_format'] = p.get('min_format'); r['max_format'] = p.get('max_format')
            r['overlays'] = len((j.get('overlays') or {}).get('entries', []))
        except Exception: r['mcmeta_error'] = True
    kinds = collections.Counter(); ksize = collections.Counter(); ns = set()
    for i in infos:
        m = re.match(r'^assets/([^/]+)/(.+)$', i.filename)
        if not m: kinds['_other'] += 1; continue
        ns.add(m.group(1)); rest = m.group(2).split('/')
        k = rest[0]
        if k == 'textures' and len(rest) > 2: k = 'textures/' + rest[1]
        elif k == 'shaders': k = 'shaders/' + (rest[1] if len(rest) > 2 else '')
        kinds[k] += 1; ksize[k] += i.file_size
    r['asset_kinds'] = dict(kinds.most_common(30)); r['asset_kind_bytes'] = dict(ksize.most_common(10)); r['namespaces'] = sorted(ns)[:10]
    r['has_custom_sounds'] = kinds.get('sounds', 0) > 0; r['has_core_shaders'] = any(k.startswith('shaders') for k in kinds)
    r['has_cmd_models'] = any('custom_model_data' in i.filename for i in infos)
    r['lang_files'] = kinds.get('lang', 0)
    r['png_count'] = sum(1 for i in infos if i.filename.endswith('.png')); r['ogg_count'] = sum(1 for i in infos if i.filename.endswith('.ogg'))
    return r

def analyse_other(path):
    z = read_zip(path); r = {'ok': False}
    if not z: r['error'] = 'not a zip'; return r
    r['ok'] = True; names = z.namelist(); r['class_count'] = sum(1 for n in names if n.endswith('.class'))
    r['uncompressed'] = sum(i.file_size for i in z.infolist())
    for mf, kind in (('fabric.mod.json', 'fabric'), ('quilt.mod.json', 'quilt'), ('META-INF/neoforge.mods.toml', 'neoforge'), ('META-INF/mods.toml', 'forge')):
        if mf in names:
            r['metadata_kind'] = kind
            try:
                txt = z.read(mf).decode('utf-8', 'replace')
                if mf.endswith('.json'):
                    j = json.loads(txt, strict=False)
                    r['entrypoint_kinds'] = sorted((j.get('entrypoints') or {}).keys()) if kind == 'fabric' else sorted(((j.get('quilt_loader') or {}).get('entrypoints') or {}).keys())
                    r['environment'] = j.get('environment'); r['depends'] = sorted((j.get('depends') or (j.get('quilt_loader') or {}).get('depends') and {} or {}).keys()) if isinstance(j.get('depends'), dict) else None
                else:
                    r['toml_len'] = len(txt)
            except Exception: r['meta_error'] = True
            break
    r['mixin_configs'] = [n for n in names if n.endswith('.mixins.json') or 'mixins' in n and n.endswith('.json')][:5]
    r['mixin_classes'] = sum(1 for n in names if '/mixin/' in n and n.endswith('.class'))
    r['has_datagen'] = any('/datagen/' in n for n in names)
    r['has_loot_tables_data'] = sum(1 for n in names if '/loot_table' in n)
    return r

def main():
    out = BASE + '/analysis/per_item.jsonl'
    done = set()
    if os.path.exists(out):
        for l in open(out): done.add(json.loads(l)['project_id'])
    with open(out, 'a') as fo:
        for l in open(BASE + '/catalog.jsonl'):
            row = json.loads(l)
            if row['project_id'] in done: continue
            pth = row['staged_path']
            if not os.path.exists(pth): continue
            fn = {'plugin': analyse_plugin, 'datapack': analyse_datapack, 'resourcepack': analyse_resourcepack, 'other-loader': analyse_other}[row['platform']]
            try: a = fn(pth)
            except Exception as e: a = {'ok': False, 'error': repr(e)}
            a.update(project_id=row['project_id'], slug=row['slug'], platform=row['platform'], primary_category=row['primary_category'], selected_categories=row['selected_categories'], downloads=row['downloads'], size=row['size'])
            fo.write(json.dumps(a) + '\n'); fo.flush()

main()
